selected.compute:
options=read('/input/options')
result=None
for count in range(goal['min_count'],goal['max_count']+1):
    for group in combinations(options,count):
        proposal=[row['id'] for row in group]
        if valid(proposal):
            result=proposal
            break
    if result is not None:
        break

selected.effects:
if exists('/output/selection'):
    selection=read('/output/selection')
else:
    write('/output/selection',result)
    selection=result
if status('report')=='not_sent':
    send('report','team',selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')
